mapper.update:
UPDATE detail_score
SET best_correct_count = CASE
        WHEN #{correctCount} > best_correct_count THEN #{correctCount}
        ELSE best_correct_count END,
    best_answer_time_ms = CASE
        WHEN #{correctCount} > best_correct_count THEN #{answerTimeMs}
        WHEN #{correctCount} = best_correct_count AND #{answerTimeMs} < best_answer_time_ms THEN #{answerTimeMs}
        ELSE best_answer_time_ms END,
    achieved_at = NOW()
WHERE user_id = #{userId}
  AND ( #{correctCount} > best_correct_count
        OR ( #{correctCount} = best_correct_count AND #{answerTimeMs} < best_answer_time_ms ) )
